# -*- coding: utf-8 -*-
from pathlib import Path
import json, html, hashlib
root=Path(__file__).resolve().parent.parent
files=['results.json','edge-results.json','final-results.json','ui-results.json','row-results.json']
reports=[json.loads((root/'tests'/f).read_text()) for f in files]
rows=[r for d in reports for r in d['results']]
passed=sum(r['status']=='PASS' for r in rows); failed=len(rows)-passed
body=''.join(f'<tr><td>{i}</td><td>{html.escape(r["name"])}</td><td class="{r["status"].lower()}">{r["status"]}</td><td>{html.escape(r.get("detail","")) or "—"}</td></tr>' for i,r in enumerate(rows,1))
sha=hashlib.sha256((root/'SEVAGO_Advanced_Data_Table.html').read_bytes()).hexdigest()
page=f'''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SEVAGO · Báo cáo kiểm thử</title><style>*{{box-sizing:border-box}}body{{font:14px/1.6 system-ui,sans-serif;color:#24352f;background:#f5f6f7;margin:0;padding:32px}}main{{max-width:1200px;margin:auto;background:white;padding:28px;border:1px solid #e5e7eb;border-radius:8px}}h1{{font-size:24px;margin:0;color:#07554b}}h2{{font-size:17px;margin:24px 0 8px}}.summary{{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}}.summary span{{border:1px solid #e5e7eb;padding:8px 14px;border-radius:6px}}.pass{{color:#027a48;font-weight:600}}.fail{{color:#b42318;font-weight:600}}table{{border-collapse:collapse;width:100%;font-size:13px}}th,td{{text-align:left;border:1px solid #e5e7eb;padding:8px;vertical-align:top}}th{{background:#f3f7f6;position:sticky;top:0}}small{{color:#67736e}}a{{color:#07554b}}code{{font-size:11px;overflow-wrap:anywhere}}.table-wrap{{overflow:auto}}li{{margin:6px 0}}figure{{margin:16px 0}}figure img{{width:100%;height:auto;border:1px solid #e5e7eb}}figcaption{{font-size:12px;color:#67736e}}</style><main><h1>SEVAGO · Bảng kiểm thử chức năng</h1><p>Kiểm thử tự động bằng Playwright/Chrome và kiểm tra ảnh desktop/tablet. Bản cập nhật giữ layout, dữ liệu, cấu trúc và hàng 36px.</p><div class="summary"><span class="pass">PASS {passed}</span><span class="{'fail' if failed else 'pass'}">FAIL {failed}</span><span>Lỗi JavaScript: {sum(len(d['errors']) for d in reports)}</span><span>1.200 Order · 34 Cell types</span></div><p><a href="SEVAGO_Advanced_Data_Table.html">Mở HTML độc lập</a> · <a href="previews/desktop.png">Desktop</a> · <a href="previews/tablet.png">Tablet</a></p><h2>Các chỉnh sửa UI đã xác nhận</h2><ul><li>Cột đầu hiển thị STT; hover chuyển sang checkbox, hàng đã chọn giữ checkbox. Header đủ ba trạng thái; số thứ tự theo dữ liệu đã lọc/sort và phân trang. Cột vẫn sticky 46px, hàng 36px.</li><li>Header bỏ icon loại dữ liệu. Nút menu chỉ hiện khi hover/focus; title và độ rộng cột không dịch chuyển. Resize, auto-fit, pin, sort và menu vẫn hoạt động.</li><li>Active border <code>#316BFF</code>; range background <code>#EBF1FF</code>; range border <code>#ADC5FF</code>. Copy không hiển thị viền hoặc khung phụ. Ctrl/Cmd+C lấy đủ giá trị, không lấy dấu ellipsis.</li><li>Cell text thực sự tràn mở overlay trắng viền xanh dương, word wrap tại cell; không đổi chiều cao hàng/độ rộng cột. Click ngoài/chọn cell khác/Esc/scroll/resize đóng preview. Drag/Shift chọn vùng không mở preview. Preview chuyên dụng ảnh/tệp/tag được giữ lại.</li></ul><figure><img src="previews/blue-range.png" alt="Vùng chọn cell xanh dương"><figcaption>Active Cell và Selected Range dùng các token theo ảnh tham chiếu.</figcaption></figure><figure><img src="previews/expanded-cell.png" alt="Preview nội dung tràn ngay tại cell"><figcaption>Expanded Cell Preview ở vị trí cell, giữ Row Height 36px.</figcaption></figure><h2>Chi tiết Pass/Fail</h2><div class="table-wrap"><table><thead><tr><th>#</th><th>Ca kiểm thử</th><th>Kết quả</th><th>Vấn đề</th></tr></thead><tbody>{body}</tbody></table></div><h2>Phạm vi và giới hạn kiểm thử</h2><ul><li>Chrome desktop; viewport 390–1728px, localhost và file:// offline. Chưa kiểm thử Safari/Firefox hoặc cảm ứng trên thiết bị thật.</li><li>Phân quyền và Planned Order vẫn là mô phỏng frontend; dữ liệu lưu localStorage theo origin.</li><li>Ảnh dùng asset Figma gốc. Preview attachment hiện hỗ trợ TXT và ảnh; chưa tích hợp đọc PDF/Office/STEP.</li><li>Cột ghim vượt bề rộng khả dụng tạm cuộn trên màn hình hẹp và khôi phục khi đủ không gian.</li></ul><p><small>Lần kiểm thử mới nhất: {html.escape(max(d['at'] for d in reports))}. Dữ liệu máy đọc: tests/results.json, edge-results.json, final-results.json, ui-results.json.</small></p><p><small>SHA-256 của HTML hiện tại:</small><br><code>{sha}</code></p></main></html>'''
(root/'TEST_REPORT.html').write_text(page)
print({'total':len(rows),'pass':passed,'fail':failed,'sha256':sha})
assert not failed
assert (root/'index.html').read_bytes()==(root/'SEVAGO_Advanced_Data_Table.html').read_bytes()
